    };
  }

  return {
    reply:
      request.action === "match"
        ? `我先按当前岗位做了一轮匹配检查。${matchHint} 下面这版建议会优先强化你已经有的证据，避免写成空泛套话。`
        : `我先按你当前这部分内容做了本地练习模式下的改写建议，重点是压缩空话、补动作和结果。`,
