.intake-status-badge,
.source-chip,
.missing-field-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: 999px;
  font-size: var(--text-micro);
  line-height: var(--leading-micro);
}

.intake-status-badge {
  padding: 6px 10px;
  color: var(--muted);
  background: var(--surface-muted);
}

.intake-status-badge.confirmed {
  color: var(--accent-strong);
  background: var(--accent-soft);
}

.intake-status-badge.review,
.intake-status-badge.draft {
  color: var(--warn);
  background: var(--warn-soft);
}

.intake-review-block {
  display: grid;
  gap: var(--space-sm);
  padding: var(--space-md);
  border: 0.5px solid var(--line);
  border-radius: var(--radius-lg);
  background: var(--surface);
}

.intake-review-block header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-sm);
}

.intake-raw-text {
  color: var(--muted);
  white-space: pre-wrap;
}

.source-chip {
  padding: 4px 8px;
  color: var(--muted);
  background: var(--surface-muted);
}

.source-chip.raw {
  color: var(--blue);
  background: var(--blue-bg);
}

.source-chip.inferred {
  color: var(--warn);
  background: var(--warn-soft);
}

.source-chip.confirmed {
  color: var(--accent-strong);
  background: var(--accent-soft);
}

.intake-field-list,
.missing-field-list {
  display: grid;
  gap: var(--space-sm);
}

.intake-field-row {
  display: grid;
  gap: 6px;
}

.intake-field-row > span {
  color: var(--subtle);
  font-size: var(--text-caption);
}

.intake-field-input {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
}

.intake-field-input .input {
  flex: 1 1 auto;
}

.missing-field-chip {
  width: fit-content;
  padding: 6px 10px;
  color: var(--warn);
  background: var(--warn-soft);
}

.review-actions {
  justify-content: flex-end;
}

.home-position-head h2 {
  color: var(--ink);
  font-size: var(--text-h2);
  font-weight: 500;
  line-height: var(--leading-h);
}

.home-position-head p {
  max-width: 760px;
  color: var(--muted);
  font-size: var(--text-body-sm);
}

.home-thread-wide {
  min-height: 140px;
}

.thread-expand-button {
  justify-self: center;
  color: var(--subtle);
  font-size: var(--text-caption);
}

.chat-bubble {
  max-width: min(100%, 820px);
  padding: 16px 18px;
  border: 0.5px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
}

.chat-bubble.user {
  justify-self: end;
  color: var(--muted);
  background: var(--accent-soft);
}

.chat-bubble.assistant {
  justify-self: start;
}

.home-intake-box {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: var(--space-xs);
  align-items: end;
  padding: 12px;
  border: 0.5px solid var(--line);
  border-radius: 18px;
  background: var(--surface);
}

.home-intake-box-wide {
  gap: var(--space-sm);
}

.home-intake-box-lollipop {
  position: relative;
  padding: 18px;
  border-radius: 22px;
  background: var(--surface);
}

.home-intake-label {
  display: block;
  grid-column: 1 / -1;
  color: var(--subtle);
  font-size: var(--text-caption);
  line-height: var(--leading-caption);
}

.home-intake-box textarea {
  width: 100%;
  min-height: 156px;
  max-height: 280px;
  padding: 16px 18px;
  resize: vertical;
  border: 0;
  outline: 0;
  color: var(--ink);
  background: transparent;
  font-size: 16px;
  line-height: 1.7;
}

.home-intake-box-lollipop textarea {
  min-height: 180px;
  padding: 10px 4px 4px;
}

.home-intake-box textarea::placeholder,
.input::placeholder,
.textarea::placeholder,
.chat-composer textarea::placeholder {
  color: var(--subtle);
}

.home-prompt-row {
  justify-content: flex-start;
}

.home-intake-actions {
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  min-width: 132px;
}

.home-send-button {
  min-height: 40px;
  padding-inline: 16px;
}

.home-suggestion-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-sm);
}

.home-suggestion-grid-lollipop {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.prompt-chip {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: start;
  gap: var(--space-xs);
  min-height: 56px;
  padding: 14px 16px;
  border: 0.5px solid var(--line);
  border-radius: 16px;
  color: var(--muted);
  background: color-mix(in srgb, var(--surface) 82%, var(--surface-muted));
  font-size: var(--text-body-sm);
  line-height: 1.55;
  text-align: left;
  white-space: normal;
  word-break: break-word;
  max-width: 100%;
}

.prompt-chip span {
  min-width: 0;
}

.suggestion-chip:hover,
.suggestion-chip:focus-visible {
  outline: none;
  border-color: var(--green-border);
  color: var(--ink);
  background: var(--surface);
}

.home-draft-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: var(--space-md);
  align-items: center;
  padding: var(--space-md) 18px;
  background: color-mix(in srgb, var(--surface) 88%, var(--surface-muted));
}

.home-draft-card strong {
  display: block;
  margin-top: 4px;
  font-size: var(--text-h3);
  font-weight: 500;
}

.home-draft-card p {
  color: var(--muted);
  font-size: var(--text-caption);
  line-height: var(--leading-caption);
}

.home-position-section {
  display: grid;
  gap: var(--space-sm);
  margin-top: var(--space-sm);
}

.home-position-section h2 {
  font-size: var(--text-h2);
  font-weight: 500;
}

.home-position-list {
  display: grid;
  gap: var(--space-xs);
}

.home-stage-product {
  gap: 14px;
  padding-top: 10px;
}

.home-hero-product {
  width: min(100%, 920px);
  justify-items: center;
  gap: 10px;
  margin-inline: auto;
  text-align: center;
}

.home-hero-product h1 {
  font-size: 46px;
  font-weight: 700;
  letter-spacing: -0.04em;
}

.home-hero-product p {
  max-width: 720px;
  color: #667085;
  font-size: 16px;
  line-height: 1.55;
}

.home-hero-topline {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  flex-wrap: wrap;
}

.home-product-shell {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 18px;
  align-items: stretch;
  width: min(100%, 1040px);
  margin-inline: auto;
}

.home-hero-input-card,
.home-current-position-card {
  min-width: 0;
  border-radius: 18px;
  background: #fff;
  box-shadow: 0 8px 28px rgba(15, 23, 42, 0.05);
}

.home-hero-input-card .surface-card-inner,
.home-current-position-card .surface-card-inner {
  gap: 14px;
  padding: 18px 20px;
}

.home-dialog-intro {
  display: grid;
  gap: 4px;
}

.home-dialog-intro h2 {
  font-size: 29px;
  font-weight: 700;
  line-height: 1.2;
}

.home-dialog-intro p {
  color: #667085;
  font-size: 14px;
  line-height: 1.7;
}

.home-intake-box-product {
  padding: 0;
  border: 1px solid #e7ecf2;
  border-radius: 18px;
  background: #fff;
  overflow: hidden;
}

.home-dialog-shell {
  display: grid;
  min-height: 240px;
}

.home-intake-box-product textarea {
  min-height: 176px;
  max-height: 420px;
  padding: 18px 20px 12px;
  border: 0;
  background: #fff;
  color: #1f2937;
  font-size: 14px;
  line-height: 1.7;
  resize: vertical;
}

.home-dialog-footer {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: end;
  min-height: 48px;
  border-top: 1px solid #edf1f5;
  background: linear-gradient(180deg, #ffffff 0%, #fafcfb 100%);
}

.home-dialog-footer-spacer {
  min-height: 48px;
}

.home-intake-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  padding: 10px 12px;
}

.home-intake-actions .button {
  width: auto;
}

.home-attach-button {
  color: #667085;
}

.onboarding-hint {
  padding: 0 0 10px;
  border-bottom: 0.5px solid var(--line);
}

.onboarding-steps {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  font-size: var(--text-body-sm);
  font-weight: 500;
}

.step {
  padding: 4px 10px;
  border-radius: 8px;
  color: var(--ink);
  background: var(--surface-muted);
}

.step-arrow {
  color: var(--subtle);
  font-size: var(--text-caption);
}

.onboarding-desc {
  margin-top: 8px;
  color: var(--muted);
  font-size: var(--text-caption);
  line-height: 1.6;
}

.home-suggestion-grid-product {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.home-current-position-card .surface-card-inner {
  gap: 14px;
}

.home-current-position-strip {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 184px;
  gap: 18px;
  align-items: stretch;
}

.home-current-position-copy {
  display: grid;
  gap: 8px;
}

.home-current-position-copy h2 {
  font-size: 28px;
  font-weight: 700;
  line-height: 1.25;
}

.home-current-position-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.home-current-position-actions .button {
  min-width: 136px;
}

.home-position-collection {
  display: grid;
  gap: 10px;
}

.home-position-section,
.home-position-section-wide {
  display: none;
}

.home-mini-status-card {
  display: grid;
  gap: var(--space-xs);
  padding: 16px;
  border: 1px solid #cfe9dd;
  border-radius: 14px;
  background: #eef9f4;
}

.home-mini-status-card span {
  color: #7d8b99;
  font-size: 12px;
}

.home-mini-status-card strong {
  color: #1f2937;
  font-size: 24px;
  font-weight: 700;
}

.home-guest-hint {
  color: var(--subtle);
  font-size: var(--text-caption);
  line-height: 1.6;
}

.home-position-strip {
  display: none;
}

.home-position-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(236px, 1fr));
  gap: 10px;
}

.home-position-card {
  display: grid;
  gap: var(--space-xs);
  width: 100%;
  min-width: 0;
  padding: 16px;
  border: 1px solid #e8edf2;
  border-left: 3px solid transparent;
  border-radius: 16px;
  color: inherit;
  background: #fff;
  text-align: left;
}

.home-position-card--active,
.home-position-card[data-active="true"] {
  border-left-color: var(--accent);
  background: #f4fbf7;
}

.home-position-card--active .home-position-title,
.home-position-card[data-active="true"] .home-position-title {
  font-weight: 600;
}

.badge-current {
  justify-self: end;
  padding: 2px 6px;
  border-radius: 4px;
  color: var(--info);
  background: var(--info-soft);
  font-size: 11px;
  line-height: 1.4;
}

.home-position-head {
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  margin-bottom: 0;
}

.home-position-title {
  color: var(--ink);
  font-size: var(--text-body);
  line-height: var(--leading-body);
}

.home-position-status,
.home-position-summary {
  color: var(--muted);
  font-size: var(--text-caption);
  line-height: 1.6;
}

/* ===== 会议监听 / Windows 音频桥 ===== */
.audio-bridge-page {
  max-width: 1180px;
}

.audio-bridge-header {
  align-items: start;
}

.audio-bridge-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(280px, 0.65fr);
  gap: 14px;
}

.audio-bridge-connect-card {
  min-width: 0;
}

.audio-bridge-events-card {
  grid-column: 1 / -1;
}

.audio-bridge-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 32px;
  padding: 6px 10px;
  border: 1px solid #e8edf2;
  border-radius: 8px;
  color: #667085;
  background: #f7f8fa;
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
}

.audio-bridge-status.active {
  border-color: #cfe9dd;
  color: #166534;
  background: #eef9f4;
}

.audio-bridge-login-state {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  padding: 16px;
  border: 1px solid #e8edf2;
  border-radius: 12px;
  background: #fafcfb;
}

.audio-bridge-login-state strong {
  display: block;
  margin-bottom: 4px;
  color: #1f2937;
}

.audio-bridge-status-panel,
.audio-bridge-steps,
.audio-bridge-command,
.audio-bridge-code-card {
  display: grid;
  gap: 8px;
  padding: 16px;
  border: 1px solid #e8edf2;
  border-radius: 12px;
  background: #fff;
}

.audio-bridge-status-panel span,
.audio-bridge-command summary,
.audio-bridge-code-card span {
  color: #667085;
  font-size: 12px;
  font-weight: 600;
}

.audio-bridge-steps {
  gap: 10px;
}

.audio-bridge-step {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 10px;
  align-items: start;
  padding: 10px;
  border: 1px solid #edf1f5;
  border-radius: 10px;
  background: #fafcfb;
}

.audio-bridge-step > span {
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  color: #667085;
  background: #eef2f6;
  font-size: 13px;
  font-weight: 700;
}

.audio-bridge-step strong {
  display: block;
  color: #1f2937;
  font-size: 14px;
}

.audio-bridge-step p {
  margin-top: 2px;
  color: #667085;
  font-size: 13px;
  line-height: 1.45;
}

.audio-bridge-step.active {
  border-color: #cfe9dd;
  background: #f4fbf7;
}

.audio-bridge-step.done > span,
.audio-bridge-step.active > span {
  color: #166534;
  background: #dff3e8;
}

.audio-bridge-status-panel strong {
  color: #1f2937;
  font-size: 20px;
  line-height: 1.35;
}

.audio-bridge-code-card {
  position: relative;
  background: #f8fbff;
}

.audio-bridge-code-card strong {
  color: #111827;
  font-family: "SF Mono", Consolas, monospace;
  font-size: 34px;
  letter-spacing: 0.18em;
  line-height: 1.1;
}

.audio-bridge-code-card .button {
  justify-self: start;
}

.audio-bridge-command code {
  display: block;
  width: 100%;
  overflow-x: auto;
  padding: 10px 12px;
  border-radius: 8px;
  color: #344054;
  background: #f3f5f7;
  font-size: 13px;
}

.audio-bridge-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.audio-bridge-device-list,
.audio-bridge-event-list {
  display: grid;
  gap: 10px;
}

.audio-bridge-device {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 12px;
  border: 1px solid #e8edf2;
  border-radius: 10px;
  background: #fff;
}

.audio-bridge-device strong {
  color: #1f2937;
}

.audio-bridge-device p {
  margin-top: 2px;
  color: #667085;
  font-size: 12px;
}

.audio-bridge-event {
  display: grid;
  gap: 4px;
  padding: 12px;
  border: 1px solid #e8edf2;
  border-left: 3px solid #98a2b3;
  border-radius: 10px;
  background: #fff;
}

.audio-bridge-event.success {
  border-left-color: #16a34a;
}

.audio-bridge-event.error {
  border-left-color: #dc2626;
}

.audio-bridge-event span {
  color: #667085;
  font-size: 12px;
}

.audio-bridge-event p {
  color: #344054;
  font-size: 14px;
}

@media (max-width: 960px) {
  .audio-bridge-layout {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (max-width: 640px) {
  .audio-bridge-login-state {
    grid-template-columns: minmax(0, 1fr);
  }

  .audio-bridge-code-card strong {
    font-size: 28px;
  }

  .audio-bridge-actions,
  .audio-bridge-header .record-report-actions {
    display: grid;
  }
}

/* ===== 模拟面试配置页 ===== */
