      if (db.db) {
        db.db.prepare("insert into audit_events(id, user_id, action, detail, created_at) values (?, ?, ?, ?, ?)")
          .run(makeId("audit"), user.id, "register", JSON.stringify({ phone: user.phone }), nowIso());
      }

