      }

      const tokens = internalCreateSession(user.id);
      if (db.db) {
        db.db.prepare("insert into audit_events(id, user_id, action, detail, created_at) values (?, ?, ?, ?, ?)")
          .run(makeId("audit"), user.id, "login", JSON.stringify({ phone: user.phone }), nowIso());
