  "content": "import { useMicVAD } from "@ricky0123/vad-react";
import {
  AlertTriangle,
  BookOpen,
  Database,
  Headphones,
  Loader2,
  LogOut,
  Mic,
  MonitorSpeaker,
  Pencil,
  Play,
  RefreshCw,
  Send,
  Sparkles,
} from "lucide-react";
import { startTransition, useCallback, useEffect, useMemo, useRef, useState, type MutableRefObject } from "react";
import {
  createPositionOnServer,
  fetchStateSnapshot,
  listAudioBridgeDevicesOnServer,
  reconstructCueCard,
