function mergeGaps(existing: Position["matchReport"]["gaps"], risks: string[]): Position["matchReport"]["gaps"] {
  const next = [...existing];
  risks.forEach((risk) => {
    if (next.some((item) => item.description === risk)) return;
    next.push({ label: "资料缺口", type: "risk", description: risk });
  });
